mapper.select:
/* refCommonMapper.select_tabdata_list */
SELECT ROW_NUMBER() OVER(ORDER BY col_seq DESC) rownum , A.col_seq AS fd_seq , A.col_varchar AS fd_varchar , A.col_int AS fd_int , A.col_datetime AS fd_datetime FROM lab_tabdata A WHERE (1=1)
AND (A.col_seq = #{tabdata_seq})

mapper.insert:
/* refCommonMapper.insert_tabdata */

    SELECT SCOPE_IDENTITY()

INSERT INTO lab_tabdata (
    col_varchar
    , col_int
    , col_datetime
)
VALUES (
    #{fd_varchar}
    , #{fd_int}
    , #{fd_datetime}
)

mapper.update:
/* refCommonMapper.update_tabdata */
UPDATE lab_tabdata
SET col_varchar = #{fd_varchar}
  , col_int = #{fd_int}
  , col_datetime = NOW()
WHERE (col_seq = #{tabdata_seq})

